/* ── Bridge: map legacy vars → themes.css semantic vars ── */
:root {
  --bg:         var(--bg-primary);
  --bg2:        var(--bg-secondary);
  --bg3:        var(--bg-tertiary);
  --border:     var(--border-default);
  --text:       var(--text-primary);
  --muted:      var(--text-secondary);
  --dim:        var(--text-muted);
  --accent-bg:  var(--accent-subtle);
  --warn:       var(--warning);
  --warn-bg:    var(--warning-bg);
  --danger:     var(--error);
  --danger-bg:  var(--error-bg);

  /* ── Typography ── */
  --ui:         var(--font-default, 'DM Sans', sans-serif);
  --mono:       'JetBrains Mono', var(--font-mono, monospace);

  /* ── Shape ── */
  --radius:     6px;
  --radius-lg:  10px;

  /* ── Layout ── */
  --hdr:        60px;
  --bar:        40px;

  /* ── Typography shared ── */
  --line-h:     1.7;
  --mono-sz:    12.5px;

  /* ── Elevation ── */
  --shadow-sm:  0 2px 8px rgba(0,0,0,.2);
  --shadow-md:  0 8px 24px rgba(0,0,0,.28);
  --shadow-lg:  0 16px 48px rgba(0,0,0,.4);

  /* ── Accent foreground ── */
  --on-accent:  var(--accent-fg, #fff);
}

/* LxCode Studio v2 — Base Styles
   Shared by all pages: reset, header, layout, toolbar, buttons, ace.
   Phase 2 migration from assets/css/main.css. */

@import './themes.css';
@import './editor.css';
@import './variables.css';

/* ── Reset ──────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
:focus:not(:focus-visible) { outline: none; }

html, body {
  min-height: 100vh;
  font-family: var(--ui);
  background: var(--bg);
  color: var(--text);
  font-size: 13px;
  transition: background .2s, color .2s;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

/* ── Header ─────────────────────────────────────────── */
#hdr {
  height: var(--hdr);
  background: var(--bg2);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 16px;
  gap: 8px;
}
#hdr.hub {
  padding: 0 24px;
  position: sticky;
  top: 0;
  z-index: 10;
}

/* ── Back button ─────────────────────────────────────── */
.back-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  text-decoration: none;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 8px;
  border-radius: var(--radius);
  transition: color .12s, background .12s;
  flex-shrink: 0;
}
.back-btn:hover { color: var(--text); background: var(--bg3); }
.back-btn svg   { width: 14px; height: 14px; }

.hdr-div, .hdr-sep { width: 1px; height: 20px; background: var(--border); flex-shrink: 0; }
.hdr-right { margin-left: auto; display: flex; gap: 6px; align-items: center; }

/* ── Logo (hub) ──────────────────────────────────────── */
.logo      { display: flex; align-items: center; gap: 10px; }
.logo-icon {
  width: 34px; height: 34px;
  background: linear-gradient(135deg, #58a6ff, #3fb950);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--mono); font-size: 12px; font-weight: 700; color: #fff;
}
.logo-name { font-weight: 700; font-size: 17px; letter-spacing: -.4px; }
.logo-sub  { font-size: 12px; color: var(--muted); font-weight: 500; }
.logo-ver  {
  font-size: 10px; color: var(--muted);
  background: var(--bg3); border: 1px solid var(--border);
  border-radius: 20px; padding: 1px 8px;
  font-family: var(--mono);
}

/* ── Brand (tool pages) ──────────────────────────────── */
.brand      { display: flex; align-items: center; gap: 8px; }
.brand-icon {
  width: 26px; height: 26px;
  border-radius: var(--radius);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--mono); font-size: 10px; font-weight: 700;
  color: #fff; letter-spacing: -.3px; flex-shrink: 0;
}
.brand-name { font-weight: 600; font-size: 14px; letter-spacing: -.3px; }
.brand-sub  { font-size: 11px; color: var(--muted); display: none; }
@media (min-width: 600px) { .brand-sub { display: inline; } }

/* ── Theme Picker ────────────────────────────────────── */
.theme-picker { position: relative; }
.theme-btn {
  display: flex; align-items: center; gap: 6px;
  height: 30px; padding: 0 11px;
  border: 1px solid var(--border); border-radius: 20px;
  background: var(--bg3); color: var(--muted);
  font-family: var(--ui); font-size: 12px; font-weight: 500;
  cursor: pointer; white-space: nowrap; flex-shrink: 0;
  transition: color .12s, background .12s, border-color .12s;
}
.theme-btn:hover { color: var(--text); border-color: var(--muted); }
.theme-btn .chevron { width: 11px; height: 11px; flex-shrink: 0; }
.tdot {
  width: 11px; height: 11px; border-radius: 50%;
  border: 1.5px solid transparent; flex-shrink: 0; display: inline-block;
}
.theme-menu {
  position: absolute; top: calc(100% + 6px); right: 0;
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 4px;
  min-width: 152px; z-index: 200;
  box-shadow: 0 8px 24px rgba(0,0,0,.28);
}
.topt, .topt-mode {
  display: flex; align-items: center; gap: 8px;
  width: 100%; padding: 5px 10px;
  border: none; border-radius: var(--radius);
  background: transparent; color: var(--muted);
  font-family: var(--ui); font-size: 12px; font-weight: 500;
  cursor: pointer; text-align: left;
  transition: background .1s, color .1s;
}
.topt:hover, .topt-mode:hover { background: var(--bg3); color: var(--text); }
.topt.active { color: var(--accent); }
.topt svg, .topt-mode svg { width: 13px; height: 13px; flex-shrink: 0; }
.tmenu-sep { height: 1px; background: var(--border); margin: 3px 6px; }

/* ── Layout (tool pages) ─────────────────────────────── */
#layout {
  display: flex;
  height: calc(100dvh - var(--hdr));
  overflow: hidden;
}
.panel  { display: flex; flex-direction: column; overflow: hidden; min-width: 120px; }
.panel-left  { flex: 0 0 50%; border-right: 1px solid var(--border); }
.panel-right { flex: 1 1 0; }
@media (max-width: 767px) {
  #layout { flex-direction: column; }
  .panel-left  { flex: 0 0 50%; border-right: none; border-bottom: 1px solid var(--border); }
  .panel-right { flex: 1 1 0; }
}

/* ── Toolbar ─────────────────────────────────────────── */
.toolbar {
  height: var(--bar);
  background: var(--bg2);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 10px 0 0;
  gap: 3px;
  flex-shrink: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.toolbar::-webkit-scrollbar { display: none; }
.tlabel {
  font-size: 10px; font-weight: 600; text-transform: uppercase;
  letter-spacing: .7px; color: var(--muted); flex-shrink: 0; margin-right: 4px;
  position: sticky; left: 0; background: var(--bg2); z-index: 1; padding: 0 10px 0 10px;
  align-self: stretch; display: flex; align-items: center;
}
.tsep { width: 1px; height: 16px; background: var(--border); margin: 0 4px; flex-shrink: 0; }
.tspc { background: transparent; margin: 0 4px; flex-shrink: 0; }

/* ── Buttons ─────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; gap: 4px;
  height: 26px; padding: 0 9px;
  background: transparent; border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--text); font-family: var(--ui); font-size: 11.5px; font-weight: 500;
  cursor: pointer; white-space: nowrap; flex-shrink: 0;
  transition: color .12s, background .12s, border-color .12s;
}
.btn:hover     { color: var(--text); background: var(--bg3); border-color: var(--border); }
.btn.active    { color: var(--accent); background: var(--accent-bg); border-color: var(--accent); }
.btn-icon      { width: 26px; padding: 0; justify-content: center; }
.btn-primary   { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { opacity: .85; color: #fff; }
.btn-run       { background: var(--success); border-color: var(--success); color: #fff; }
.btn-run:hover { opacity: .85; color: #fff; }
.btn svg       { width: 13px; height: 13px; flex-shrink: 0; }

/* ── Ace editor container ────────────────────────────── */
.ace-wrap { flex: 1; width: 100%; min-height: 0; overflow: hidden; }

/* ── Scaffold notice (Phase 1 only — removed in Phase 4) */
.scaffold-notice {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 60vh;
  gap: 12px;
  font-family: var(--mono);
}
.scaffold-notice h1 { font-size: 1.4rem; color: var(--accent); letter-spacing: -.03em; }
.scaffold-notice p  { font-size: 0.8rem; color: var(--muted); }
.scaffold-notice a  { font-size: 0.75rem; color: var(--dim); text-decoration: none; }
.scaffold-notice a:hover { color: var(--accent); }

/* Font loaded via <link> in HTML — no CSS @import to avoid render-blocking cascade */

/* ================================================================
 * DESIGN SYSTEM PALETTE — themes.css
 * ----------------------------------------------------------------
 *  Themes  : Lumen  ·  Terra  ·  Verdant  ·  Aether  ·  Mystique  ·  Roséa  ·  Obsidian
 *  Modes   : Light · Dark
 *  Ramps   : 9 color ramps (primitives, do not use directly)
 *  Standard: WCAG AA / AAA compliant
 * ----------------------------------------------------------------
 *
 *  QUICK START
 *  ───────────
 *  1. Link in HTML:
 *       <link rel="stylesheet" href="themes.css">
 *
 *  2. Set theme + mode on <html>:
 *       <html data-theme="lumen" data-mode="light">
 *
 *  3. Toggle dark mode (JS):
 *       document.documentElement.dataset.mode = "dark"
 *
 *  4. Switch theme (JS):
 *       document.documentElement.dataset.theme = "terra"  // lumen|terra|verdant|aether|mystique|rosea|obsidian
 *
 *  SEMANTIC VARIABLES
 *  ──────────────────
 *  Background  →  --bg-primary  |  --bg-secondary  |  --bg-tertiary  |  --surface
 *  Text        →  --text-primary  |  --text-secondary  |  --text-muted
 *  Border      →  --border-strong  |  --border-default  |  --border-subtle
 *  Accent      →  --accent  |  --accent-hover  |  --accent-subtle  |  --accent-fg
 *  Status      →  --success  --success-bg  --success-text
 *                 --warning  --warning-bg  --warning-text
 *                 --error    --error-bg    --error-text
 *                 --info     --info-bg     --info-text
 *
 *  EXAMPLE USAGE
 *  ─────────────
 *  body         { background: var(--bg-primary);   color: var(--text-primary); }
 *  .card        { background: var(--bg-secondary); border: 1px solid var(--border-default); }
 *  .modal       { background: var(--surface);      border: 1px solid var(--border-strong); }
 *  .caption     { color: var(--text-muted); }
 *  .btn-primary { background: var(--accent);       color: var(--accent-fg); }
 *  .btn-primary:hover { background: var(--accent-hover); }
 *  .badge       { background: var(--accent-subtle); color: var(--accent); }
 *  .alert-ok    { background: var(--success-bg);  color: var(--success-text); }
 *
 * ================================================================ */


/* ================================================================
   §1  TYPOGRAPHY SYSTEM  —  Global font families
   ────────────────────────────────────────────────────────────────
   Use semantic font variables in components, never hardcode font names.
================================================================= */

:root {
  --font-default: "Plus Jakarta Sans", sans-serif;
  --font-mono:    "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
}


/* ================================================================
   §2  COLOR RAMPS  —  9 Primitives (foundation layer)
   ────────────────────────────────────────────────────────────────
   Read-only. Never reference ramp variables directly in components.
   Use semantic variables (§3, §4) instead.
   Each ramp: 7 stops — 50 (lightest) → 900 (darkest)
================================================================= */

:root {

  /* ── 1. Gray — neutral surfaces, text, White-theme accent ── */
  --ramp-gray-50:  #F1EFE8;
  --ramp-gray-100: #D3D1C7;
  --ramp-gray-200: #B4B2A9;
  --ramp-gray-400: #888780;
  --ramp-gray-600: #5F5E5A;
  --ramp-gray-800: #444441;
  --ramp-gray-900: #2C2C2A;

  /* ── 2. Amber — warmth, highlights, Brown-theme accent ── */
  --ramp-amber-50:  #FAEEDA;
  --ramp-amber-100: #FAC775;
  --ramp-amber-200: #EF9F27;
  --ramp-amber-400: #BA7517;
  --ramp-amber-600: #854F0B;
  --ramp-amber-800: #633806;
  --ramp-amber-900: #412402;

  /* ── 3. Green — nature, growth, Green-theme accent ── */
  --ramp-green-50:  #EAF3DE;
  --ramp-green-100: #C0DD97;
  --ramp-green-200: #97C459;
  --ramp-green-400: #639922;
  --ramp-green-600: #3B6D11;
  --ramp-green-800: #27500A;
  --ramp-green-900: #173404;

  /* ── 4. Blue — trust, clarity, Blue-theme accent ── */
  --ramp-blue-50:  #E6F1FB;
  --ramp-blue-100: #B5D4F4;
  --ramp-blue-200: #85B7EB;
  --ramp-blue-400: #378ADD;
  --ramp-blue-600: #185FA5;
  --ramp-blue-800: #0C447C;
  --ramp-blue-900: #042C53;

  /* ── 5. Purple — creative, premium, Purple-theme accent ── */
  --ramp-purple-50:  #EEEDFE;
  --ramp-purple-100: #CECBF6;
  --ramp-purple-200: #AFA9EC;
  --ramp-purple-400: #7F77DD;
  --ramp-purple-600: #534AB7;
  --ramp-purple-800: #3C3489;
  --ramp-purple-900: #26215C;

  /* ── 6. Pink — romance, softness, Rose-theme surfaces ── */
  --ramp-pink-50:  #FBEAF0;
  --ramp-pink-100: #F4C0D1;
  --ramp-pink-200: #ED93B1;
  --ramp-pink-400: #D4537E;
  --ramp-pink-600: #993556;
  --ramp-pink-800: #72243E;
  --ramp-pink-900: #4B1528;

  /* ── 7. Coral — energy, bold, Rose-theme accent ── */
  --ramp-coral-50:  #FAECE7;
  --ramp-coral-100: #F5C4B3;
  --ramp-coral-200: #F0997B;
  --ramp-coral-400: #D85A30;
  --ramp-coral-600: #993C1D;
  --ramp-coral-800: #712B13;
  --ramp-coral-900: #4A1B0C;

  /* ── 8. Teal — success, calm, health ── */
  --ramp-teal-50:  #E1F5EE;
  --ramp-teal-100: #9FE1CB;
  --ramp-teal-200: #5DCAA5;
  --ramp-teal-400: #1D9E75;
  --ramp-teal-600: #0F6E56;
  --ramp-teal-800: #085041;
  --ramp-teal-900: #04342C;

  /* ── 9. Red — danger, error, alert ── */
  --ramp-red-50:  #FCEBEB;
  --ramp-red-100: #F7C1C1;
  --ramp-red-200: #F09595;
  --ramp-red-400: #E24B4A;
  --ramp-red-600: #A32D2D;
  --ramp-red-800: #791F1F;
  --ramp-red-900: #501313;

}


/* ================================================================
   §3  STATUS COLORS  —  Semantic, theme-agnostic
   ────────────────────────────────────────────────────────────────
   Shared across all themes. Same meaning regardless of hue theme.
   Overridden in .dark for dark mode contrast compliance.
================================================================= */

:root {
  --success:       var(--ramp-teal-600);   /* #0F6E56 */
  --success-bg:    var(--ramp-teal-50);    /* #E1F5EE */
  --success-text:  var(--ramp-teal-900);   /* #04342C */

  --warning:       #B45309;
  --warning-bg:    #FEF8ED;
  --warning-text:  #78350F;

  --error:         var(--ramp-red-600);    /* #A32D2D */
  --error-bg:      var(--ramp-red-50);     /* #FCEBEB */
  --error-text:    var(--ramp-red-900);    /* #501313 */

  --info:          var(--ramp-blue-600);   /* #185FA5 */
  --info-bg:       var(--ramp-blue-50);    /* #E6F1FB */
  --info-text:     var(--ramp-blue-900);   /* #042C53 */
}

/* Dark-mode status overrides — add .dark to <html> or use data-mode="dark" */
[data-mode="dark"],
.dark {
  --success:       var(--ramp-teal-200);   /* #5DCAA5 */
  --success-bg:    #1A3328;
  --success-text:  var(--ramp-teal-100);   /* #9FE1CB */

  --warning:       #FBBF24;
  --warning-bg:    #3A2800;
  --warning-text:  #FCD96A;

  --error:         var(--ramp-red-200);    /* #F09595 */
  --error-bg:      #3A1212;
  --error-text:    var(--ramp-red-100);    /* #F7C1C1 */

  --info:          var(--ramp-blue-200);   /* #85B7EB */
  --info-bg:       #1A2C48;
  --info-text:     var(--ramp-blue-100);   /* #B5D4F4 */
}


/* ================================================================
   §4  THEMES  —  7 × (Light + Dark)
================================================================= */


/* ────────────────────────────────────────────────────────────────
   LUMEN  —  Neutral · Editorial · Clean
   Draws from: Gray ramp
   Accent feel: Slate-blue (cool, composed)
   Contrast:    text-primary/bg-primary ≈ 13.1:1  (AAA)
                text-secondary/bg-primary ≈ 4.9:1  (AA)
──────────────────────────────────────────────────────────────── */
[data-theme="lumen"],
[data-theme="lumen"][data-mode="light"] {

  /* Background */
  --bg-primary:     #FAFAF8;   /* main canvas, body                     */
  --bg-secondary:   #F2F2EF;   /* subtle fills, sidebars                 */
  --bg-tertiary:    #E8E8E4;   /* hover states, input backgrounds        */
  --surface:        #FFFFFF;   /* elevated: cards, modals, dropdowns     */

  /* Text */
  --text-primary:   #2D2A26;   /* headings, body copy                    */
  --text-secondary: #6B6864;   /* labels, supporting text                */
  --text-muted:     #9C9894;   /* captions, placeholders, disabled       */

  /* Border */
  --border-strong:  #C8C5BF;   /* dividers, focused inputs               */
  --border-default: #DDDBD5;   /* default card/input borders             */
  --border-subtle:  #ECEAE6;   /* hairlines, section separators          */

  /* Accent (Slate-blue) */
  --accent:         #4A5568;   /* primary buttons, links, active states  */
  --accent-hover:   #3A4558;   /* hover on accent elements               */
  --accent-subtle:  #EDF0F3;   /* tinted backgrounds, badge fills        */
  --accent-fg:      #FFFFFF;   /* text/icons on accent background        */
}

[data-theme="lumen"][data-mode="dark"],
.dark [data-theme="lumen"] {

  --bg-primary:     #1C1E24;
  --bg-secondary:   #252830;
  --bg-tertiary:    #2F3238;
  --surface:        #303540;

  --text-primary:   #E8E8E8;
  --text-secondary: #A0A4AE;
  --text-muted:     #68707C;

  --border-strong:  #464B56;
  --border-default: #383D48;
  --border-subtle:  #2F3238;

  --accent:         #8BACC0;
  --accent-hover:   #9BBCD0;
  --accent-subtle:  #1E2430;
  --accent-fg:      #1C1E24;
}


/* ────────────────────────────────────────────────────────────────
   TERRA  —  Warm Earth · Cozy · Organic
   Draws from: Amber ramp
   Accent feel: Burnt sienna (rich, earthy)
   Contrast:    text-primary/bg-primary ≈ 10.2:1  (AAA)
                text-secondary/bg-primary ≈ 4.6:1  (AA)
──────────────────────────────────────────────────────────────── */
[data-theme="terra"],
[data-theme="terra"][data-mode="light"] {

  --bg-primary:     #F3EFE8;
  --bg-secondary:   #EDE7DD;
  --bg-tertiary:    #E4DDD3;
  --surface:        #FBF8F4;

  --text-primary:   #3F3530;
  --text-secondary: #7A6E65;
  --text-muted:     #A89C94;

  --border-strong:  #B8AFA6;
  --border-default: #C8BFB2;
  --border-subtle:  #D8D0C8;

  --accent:         #8B5E3C;
  --accent-hover:   #7A4E2C;
  --accent-subtle:  #F7ECE0;
  --accent-fg:      #FFFFFF;
}

[data-theme="terra"][data-mode="dark"],
.dark [data-theme="terra"] {

  --bg-primary:     #2C2622;
  --bg-secondary:   #352E2A;
  --bg-tertiary:    #3E3632;
  --surface:        #40382F;

  --text-primary:   #DDD4CC;
  --text-secondary: #9C8E84;
  --text-muted:     #6E6058;

  --border-strong:  #5A504A;
  --border-default: #4A4038;
  --border-subtle:  #3E3632;

  --accent:         #D4956A;
  --accent-hover:   #E4A57A;
  --accent-subtle:  #3A2C20;
  --accent-fg:      #1C1410;
}


/* ────────────────────────────────────────────────────────────────
   VERDANT  —  Natural · Fresh · Growth
   Draws from: Green ramp
   Accent feel: Forest green (grounded, trustworthy)
   Contrast:    text-primary/bg-primary ≈ 10.1:1  (AAA)
                text-secondary/bg-primary ≈ 4.8:1  (AA)
──────────────────────────────────────────────────────────────── */
[data-theme="verdant"],
[data-theme="verdant"][data-mode="light"] {

  --bg-primary:     #EEF5F0;
  --bg-secondary:   #E4EEE7;
  --bg-tertiary:    #DAE8DC;
  --surface:        #F5FAF6;

  --text-primary:   #2F3A33;
  --text-secondary: #62786A;
  --text-muted:     #8EA898;

  --border-strong:  #A8C0B0;
  --border-default: #B8CCBC;
  --border-subtle:  #CAD8CC;

  --accent:         #3A7A52;
  --accent-hover:   #2A6A42;
