/* ================================================================
   §6  TYPOGRAPHY DEFAULTS  —  Base text rendering
   ────────────────────────────────────────────────────────────────
   Applied globally to all text elements for consistency and
   accessibility. Automatically inherits theme colors via CSS vars.
================================================================= */

html,
body {
  font-family: var(--font-default);
  font-size: 16px;
  line-height: 1.6;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: var(--text-primary);
  background-color: var(--bg-primary);
}

/* Headings */
h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-default);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-top: 1.5em;
  margin-bottom: 0.5em;
}

h1 { font-size: 2.5rem;   line-height: 1.2; }
h2 { font-size: 2rem;     line-height: 1.3; }
h3 { font-size: 1.75rem;  line-height: 1.3; }
h4 { font-size: 1.5rem;   line-height: 1.4; }
h5 { font-size: 1.25rem;  line-height: 1.4; }
h6 { font-size: 1rem;     line-height: 1.5; font-weight: 600; }

/* Paragraph & text elements */
p {
  margin-top: 0;
  margin-bottom: 1em;
  font-family: inherit;
  color: var(--text-primary);
}

span,
div,
li,
td,
th {
  font-family: inherit;
  color: var(--text-primary);
}

/* Form elements */
button,
input,
textarea,
select,
label {
  font-family: var(--font-default);
  color: var(--text-primary);
}

button {
  cursor: pointer;
  border: 1px solid var(--border-default);
  background-color: var(--bg-secondary);
  padding: 8px 16px;
  border-radius: 6px;
  transition: all 0.2s ease;
}

button:hover {
  background-color: var(--bg-tertiary);
  border-color: var(--border-default);
}

input,
textarea,
select {
  padding: 8px 12px;
  border: 1px solid var(--border-default);
  border-radius: 6px;
  background-color: var(--bg-secondary);
  transition: all 0.2s ease;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-subtle);
}

/* Links */
a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-hover);
  text-decoration: underline;
}

a:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Code & pre */
code,
pre {
  font-family: var(--font-mono);
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: 4px;
  color: var(--text-primary);
}

code {
  padding: 2px 6px;
  font-size: 0.9em;
}

pre {
  padding: 1rem;
  overflow-x: auto;
  line-height: 1.5;
}

pre code {
  background: none;
  border: none;
  padding: 0;
}

/* Small text / captions */
small,
.caption,
.label {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Muted text */
.muted,
.placeholder {
  color: var(--text-muted);
}

/* Strong / Bold */
strong,
b {
  font-weight: 700;
}

/* Emphasis */
em,
i {
  font-style: italic;
}


/* ================================================================
   §7  TYPOGRAPHY UTILITY CLASSES  —  Optional semantic overrides
   ────────────────────────────────────────────────────────────────
   Use these classes to override the default font for specific
   sections or components. Example: <section class="font-editorial">
================================================================= */

.font-default {
  font-family: var(--font-default);
}

.font-modern {
  font-family: var(--font-modern);
}

.font-smooth {
  font-family: var(--font-smooth);
}

.font-tech {
  font-family: var(--font-tech);
}

.font-classic {
  font-family: var(--font-classic);
}

.font-serif {
  font-family: var(--font-serif);
}

.font-editorial {
  font-family: var(--font-editorial);
}

.font-accessibility {
  font-family: var(--font-accessibility);
}

.font-mono {
  font-family: var(--font-mono);
}

/* Icons */
.bi {
  font-family: var(--font-icon) !important;
}


/* ================================================================
   END OF THEME SYSTEM
================================================================= */

/* LxCode Studio v2 — Hub / Homepage Styles
   Loaded only on index.html (body.hub).
   Phase 2 migration from assets/css/main.css. */

/* Hub body allows scrolling */
body.hub { overflow: auto; height: auto; }

/* ── Hub main wrapper ────────────────────────────────── */
.hub-main {
  max-width: 1060px;
  margin: 0 auto;
  padding: 56px 24px 80px;
}

/* ── Hero ────────────────────────────────────────────── */
.hero         { text-align: center; margin-bottom: 64px; }
.hero h1      { font-size: 36px; font-weight: 700; letter-spacing: -.6px; margin-bottom: 14px; line-height: 1.2; }
.hero h1 span { color: var(--accent); }
.hero p       { color: var(--muted); font-size: 15px; line-height: 1.7; max-width: 520px; margin: 0 auto; }

/* ── Product section ─────────────────────────────────── */
.product-section { margin-bottom: 56px; }
.product-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}
.product-badge {
  width: 36px; height: 36px;
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.product-badge svg { width: 18px; height: 18px; color: #fff; }
.product-title { font-size: 20px; font-weight: 700; letter-spacing: -.3px; color: var(--text); }
.product-desc  { font-size: 13px; color: var(--muted); margin-top: 2px; }

/* ── Cards grid ──────────────────────────────────────── */
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 14px; }

.card {
  display: block; text-decoration: none;
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  transition: border-color .15s, transform .12s, box-shadow .15s;
  position: relative; overflow: hidden;
}
.card::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--card-c1, var(--accent)), var(--card-c2, var(--success)));
  opacity: 0; transition: opacity .15s;
}
.card:hover { border-color: var(--card-c1, var(--accent)); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,.15); }
.card:hover::before { opacity: .04; }
.card-icon {
  width: 38px; height: 38px; border-radius: 9px;
  background: linear-gradient(135deg, var(--card-c1, var(--accent)), var(--card-c2, var(--success)));
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 14px; position: relative;
  font-size: 11px; font-family: var(--mono); font-weight: 700;
  color: #fff; letter-spacing: -.3px;
}
.card-icon svg { width: 16px; height: 16px; color: #fff; }
.card-title    { font-weight: 600; font-size: 14px; margin-bottom: 6px; position: relative; color: var(--text); }
.card-desc     { font-size: 12px; color: var(--muted); line-height: 1.65; position: relative; }
.card-tags     { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 14px; position: relative; }
.tag {
  font-size: 10px; padding: 2px 8px; border-radius: 20px;
  background: var(--bg3); border: 1px solid var(--border); color: var(--muted);
}

/* ── Site footer ─────────────────────────────────────── */
.site-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 40px 0 32px;
  font-size: 12px;
  color: var(--dim);
  border-top: 1px solid var(--border);
}
.footer-brand {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: 'Lobster', cursive;
  font-size: 1.13em;
}
.footer-logo { height: 14px; width: auto; vertical-align: middle; }
@media (max-width: 599px) {
  .footer-sep     { display: none; }
  .footer-tagline { display: block; width: 100%; text-align: center; }
}
